+          const old = Services.prefs.getBoolPref(
+            "mail.prompt_purge_threshhold"
+          );
+          Services.prefs.setBoolPref("mail.prompt_purge_threshold", old);
+          Services.prefs.clearUserPref("mail.prompt_purge_threshhold");
+        } catch (ex) {}
       }

